import{factorData,multiCurves,greenhousePlans,pondRates,netReturn}from './photo-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const txt=(x,y,t,size=21)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f4eee5" font-size="${size}">${esc(t)}</text>`;
const frame=(body,aria)=>`<svg class="infection-diagram photo-diagram" viewBox="0 0 560 420" role="img" aria-label="${esc(aria)}">${body}</svg>`;
export function photoTable(head,rows){return`<table class="photo-data"><thead><tr>${head.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(x=>`<td>${esc(x)}</td>`).join('')+'</tr>').join('')}</tbody></table>`;}
export function rateGraph(points,xLabel='Distance / cm',yLabel='Oxygen rate / cm³ per min',opts={}){let xmax=opts.xmax??40,ymax=opts.ymax??6,body='<path d="M85 65V310H485" stroke="#c5d4cf" stroke-width="2" fill="none"/>';for(let v=0;v<=4;v++){let x=85+v*100,y=310-v*60;body+=txt(x,342,Number((xmax*v/4).toFixed(3)),18)+txt(55,y+5,Number((ymax*v/4).toFixed(2)),17)+`<path d="M85 ${y}H485" stroke="#708b90" stroke-width="1"/>`;}let series=opts.series||[{points,color:'#a6cbbd'}];for(let line of series){let ps=line.points.filter(([x,y])=>Number.isFinite(Number(x))&&Number.isFinite(Number(y))&&x>=0&&x<=xmax&&y>=0&&y<=ymax);body+=`<polyline points="${ps.map(([x,y])=>`${85+x/xmax*400},${310-y/ymax*240}`).join(' ')}" fill="none" stroke="${line.color}" stroke-width="4" ${line.dash?'stroke-dasharray="'+line.dash+'"':''}/>`;for(let[x,y]of ps)body+=`<circle cx="${85+x/xmax*400}" cy="${310-y/ymax*240}" r="${opts.selected===x?7:4}" fill="${line.color}"/>`;}body+=txt(280,31,yLabel,21)+txt(285,390,xLabel,21);return frame(body,yLabel+' versus '+xLabel+'. Original illustrative data.');}
export function photoFigure(w={}){let k=w.kind||'chloroplast',s=w.state||'light',body='';if(k==='factor'){let f=factorData[w.factor||s]||factorData.light;return rateGraph(f.x.map((x,i)=>[x,f.y[i]]),f.name+' / '+f.unit,'Photosynthesis rate / model units',{xmax:Math.max(...f.x),ymax:6,selected:f.x[w.index??2]})+'<p class="diagram-caption">Original single-factor comparison; other conditions suitable. Not a biological calibration.</p>';}
if(k==='limits')return rateGraph([], 'Light intensity / relative units','Rate / original model units',{xmax:100,ymax:10,series:multiCurves.map((c,i)=>({...c,color:['#a5c7b9','#e5b19a','#d9cda2'][i],dash:['','8 5','2 6'][i]}))})+'<p class="diagram-caption">Solid: low CO₂20°C · dashed: higher CO₂20°C · dotted: higher CO₂30°C.</p>'+photoTable(['Light','Low CO₂20°C','High CO₂20°C','High CO₂30°C'],[20,80].map(x=>[x,...multiCurves.map(c=>c.points.find(p=>p[0]===x)[1])]));
if(k==='graph')return rateGraph(w.points||pondRates)+'<p class="diagram-caption">Distance is measured here. Original repeated oxygen-volume observations over2min.</p>';
if(k==='greenhouse')return photoTable(['Plan','Revenue/£','Cost/£','Rate'],greenhousePlans.map(p=>[p.name,p.revenue,p.cost,p.rate]))+'<p class="diagram-caption">One fictional matched period. Calculate net return; not a business forecast.</p>';
if(k==='ledger'){body=txt(280,65,'Material ledger · not molecular detail');body+=txt(280,155,s==='after'||w.after?'C₆H₁₂O₆ +6O₂':'6CO₂ +6H₂O',34)+txt(280,225,'C:6 · H:12 · O:18',28)+txt(280,300,'Same inventory before and after',23)+txt(280,355,'Light transfers energy; no new atoms',21);}
else if(k==='chloroplast'){body='<ellipse cx="280" cy="205" rx="190" ry="105" fill="#95af9d" stroke="#d7d6ba" stroke-width="5"/>';for(let i=0;i<3;i++)for(let j=0;j<4;j++)body+=`<ellipse cx="${165+i*115}" cy="${190+j*15}" rx="35" ry="9" fill="#608b72" stroke="#c3d0ae" stroke-width="2"/>`;if(s!=='dark')body+='<path d="M100 60l65 75m115-75v75m120-75l-65 75" stroke="#edcd98" stroke-width="5"/>';body+=txt(280,335,s==='dark'?'Light input removed':'Light energy enters chloroplasts',22)+txt(280,380,'Open-envelope model · stacks enlarged',20);}
else if(['lamp','apparatus','bubbles'].includes(k)){let d=w.distance??20;body='<path d="M295 140V315H465V140" stroke="#bfd6d4" stroke-width="5" fill="#8cb9c326"/><path d="M300 175H460" stroke="#a4ced4" stroke-width="3"/><path d="M380 295V205m0 60l-25-20m25 5l25-20m-25 5l-20-20" stroke="#9bb99c" stroke-width="6"/><path d="M350 195l30-30l30 30zM380 165V95" fill="none" stroke="#d3d9cf" stroke-width="4"/><path d="M365 90V50q15-15 30 0v40" fill="none" stroke="#d3d9cf" stroke-width="4"/><path d="M95 290V125l65-25v70l-65-25M60 305H130" fill="none" stroke="#d6c2a8" stroke-width="8"/><path d="M165 125H270m-20-10l20 10l-20 10" stroke="#edd19f" stroke-width="3" fill="none"/>';for(let i=0;i<(k==='bubbles'?10:3);i++)body+=`<circle cx="${360+(i%3)*20}" cy="${k==='bubbles'?210+Math.floor(i/3)*20:150+i*20}" r="${s==='large'?8:4}" fill="#c5dddd"/>`;body+=txt(280,355,'Lamp distance: '+d+'cm · schematic scale',20)+txt(280,390,'Time and collected oxygen are measured',20);}
else if(k==='uses'){let names={respiration:'Respiration · energy transfer',starch:'Insoluble starch · storage',oil:'Fat/oil · storage',cellulose:'Cellulose · wall strength',protein:'Glucose + nitrate → amino acids/protein','nitrate-off':'Nitrate limited · protein route restricted','nitrate-on':'Glucose and nitrate support synthesis',day:'Daylight: photosynthesis + respiration',night:'Darkness: respiration continues'};body='<circle cx="110" cy="200" r="55" fill="#d4be9e"/><path d="M180 200H325l-20-15m20 15l-20 15" stroke="#ead1a6" stroke-width="4" fill="none"/><rect x="345" y="140" width="145" height="120" rx="25" fill="#9fb9ac"/>'+txt(110,210,'Glucose',20)+txt(280,65,'Different uses, different requirements',21)+txt(280,335,names[s]||s,20);if(['protein','nitrate-on'].includes(s))body+=txt(420,110,'+ nitrate',20);if(s==='nitrate-off')body+='<path d="M280 150V250" stroke="#e9aa96" stroke-width="10"/>';}
return frame(body,w.title||'Photosynthesis mechanism')+'<p class="diagram-caption">'+esc(w.result||'Symbolic colours, geometry and stages')+'</p>';}
